    def gv(key, default=None):
        if hasattr(observation, "get"):
            return observation.get(key, default)
        return default

    def is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def as_pos(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2 and is_num(x[0]) and is_num(x[1]):
            return (int(x[0]), int(x[1]))
        if isinstance(x, dict):
            for a, b in (("x", "y"), ("col", "row"), ("cx", "cy")):
                if a in x and b in x and is_num(x[a]) and is_num(x[b]):
                    return (int(x[a]), int(x[b]))
        return None

    def collect_positions(obj, out, limit=64):
        if len(out) >= limit:
            return
        p = as_pos(obj)
        if p is not None:
            out.append(p)
            return
        if isinstance(obj, dict):
            for v in obj.values():
                if len(out) >= limit:
                    break
                collect_positions(v, out, limit)
        elif isinstance(obj, (list, tuple)):
