    me = as_pos(gv("position")) or as_pos(gv("agent_position")) or as_pos(gv("self")) or (0, 0)

    w = gv("width")
    h = gv("height")
    size = gv("size")
    if (w is None or h is None) and isinstance(size, (list, tuple)) and len(size) >= 2:
        w = w if w is not None else size[0]
        h = h if h is not None else size[1]
    if isinstance(gv("map"), (list, tuple)) and gv("map"):
        mp = gv("map")
        if h is None:
            h = len(mp)
