            w = len(mp[0])

    w = int(w) if is_num(w) else None
    h = int(h) if is_num(h) else None

    blocked = set()
    for k in ("walls", "blocked", "obstacles", "rocks", "borders"):
        collect_positions(gv(k), blocked, 128)

    targets = []
    for k in (
        "resources", "resource_positions", "food", "food_positions",
        "enemies", "enemy_positions", "opponents", "opponent_positions",
        "prey", "prey_positions", "goals", "goal_positions",
        "targets", "target_positions", "capture_points", "bases",
        "unclaimed", "neutral", "territory_targets"
    ):
