        tx = (me[0] + (3 if (me[1] & 1) == 0 else -3))
        ty = (me[1] + (3 if (me[0] & 1) == 0 else -3))
        targets = [(tx, ty)]

    def dist2(a, b):
        dx = a[0] - b[0]
        dy = a[1] - b[1]
        return dx * dx + dy * dy

    # pick nearest target
    target = targets[0]
    best_d = dist2(me, target)
    for p in targets[1:]:
        d = dist2(me, p)
        if d < best_d:
            best_d = d
            target = p

    enemy_like = []
    for k in ("enemies", "enemy_positions", "opponents", "opponent_positions", "threats", "hazards"):
        collect_positions(gv(k), enemy_like, 64)

