        if (nx, ny) in blocked:
            continue
        if w is not None and (nx < 0 or nx >= w):
            continue
        if h is not None and (ny < 0 or ny >= h):
            continue

        score = 0
        # move toward target
        score -= abs(nx - target[0]) + abs(ny - target[1])

